$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'
"use strict";
const fs=require("fs"),assert=require("assert");
const source="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json";
const accepted="Tasks/TasksCompleted/user-prompt-task-1794192853-accepted-instruction.json";
const destination="references/user-defined-scope-rule.json";
assert(!fs.existsSync(destination),"Destination exists; no overwrite permitted");
const wrapper=JSON.parse(fs.readFileSync(source,"utf8"));
const original=JSON.parse(fs.readFileSync(accepted,"utf8"));
assert(Array.isArray(wrapper)&&wrapper.length>=2,"Unexpected wrapper");
const standalone=wrapper[1];
assert(!Array.isArray(standalone)&&standalone&&typeof standalone==="object");
assert(standalone.title==="User-Defined Operational Scope");
const {title,...body}=standalone;
assert.deepStrictEqual(body,original,"Accepted scope contents do not match the wrapper");
assert.strictEqual(standalone.examples.length,10);
const content=JSON.stringify(standalone,null,2)+"\n";
fs.writeFileSync(destination,content,"utf8");
assert.deepStrictEqual(JSON.parse(fs.readFileSync(destination,"utf8")),standalone);
assert.deepStrictEqual(JSON.parse(fs.readFileSync(source,"utf8"))[1],standalone);
console.log("SAVED",destination);
console.log("RULE_TITLE",standalone.title);
console.log("RETAINED_ACCEPTED_BODY",true);
console.log("RETAINED_TEN_EXAMPLES",true);
console.log("MATCHES_WRAPPER_INDEX_1",true);
console.log("BYTES",Buffer.byteLength(content));
NODE
git add -- references/user-defined-scope-rule.json
git diff --cached --check
git commit -m 'Save complete user-defined scope instruction as standalone reference'
for i in 1 2 3 4; do git fetch origin main -q; git rebase origin/main -q; if git push origin HEAD:main; then break; fi; test "$i" -lt 4; done
printf 'PUBLISHED_COMMIT ';git rev-parse HEAD
git show --stat --oneline HEAD
